<div class="admin-page-heading"><div><span class="admin-eyebrow">PORTFOLIO MANAGEMENT</span><p>Use verified project details and real project photography.</p></div><a class="admin-text-link" href="<?= e(url('/admin/projects')) ?>">← Back to projects</a></div><section class="admin-panel form-panel"><form method="post" action="<?= e(url('/admin/projects/save')) ?>" enctype="multipart/form-data" class="admin-form-grid"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($project['id']??'') ?>"><label>Project title *<input name="title" required maxlength="180" value="<?= e($project['title']??'') ?>"></label><label>URL slug<input name="slug" maxlength="200" value="<?= e($project['slug']??'') ?>" placeholder="Generated from title if empty"></label><label>Category<select name="category_id"><option value="0">Choose category</option><?php foreach($categories as $c): ?><option value="<?= e($c['id']) ?>" <?= (int)($project['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Location<input name="location" maxlength="180" value="<?= e($project['location']??'') ?>"></label><label class="span-2">Short summary<textarea name="summary" rows="2" maxlength="300"><?= e($project['summary']??'') ?></textarea></label><label class="span-2">Project description<textarea name="description" rows="5"><?= e($project['description']??'') ?></textarea></label><label>Project cover image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or WebP · max 5MB <?= !empty($project['image_path'])?'· Current image is saved':'' ?></small></label><label>Before image (optional)<input type="file" name="before_image" accept="image/jpeg,image/png,image/webp"></label><label>After image (optional)<input type="file" name="after_image" accept="image/jpeg,image/png,image/webp"></label><div class="form-checks"><label><input type="checkbox" name="is_featured" value="1" <?= !empty($project['is_featured'])?'checked':'' ?>> Featured project</label><label><input type="checkbox" name="is_published" value="1" <?= !isset($project['is_published'])||$project['is_published']?'checked':'' ?>> Publish on website</label></div><div class="span-2 admin-form-actions"><button class="admin-button" type="submit">Save Project <span>→</span></button><a class="admin-cancel" href="<?= e(url('/admin/projects')) ?>">Cancel</a></div></form></section>
